package com.library.circulation; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.library.common.*; import lombok.Data; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequiredArgsConstructor public class CirculationController{private final BorrowMapper borrows;private final ReservationMapper reservations;private final JdbcTemplate jdbc;
@GetMapping("/api/borrows")public Result<PageResult<Map<String,Object>>>page(@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="10")long size,@RequestParam(defaultValue="")String keyword){return Result.ok(new PageResult<>(borrows.count(keyword),borrows.search(keyword,(page-1)*size,size)));}
@PostMapping("/api/borrows")@Transactional public Result<Void>borrow(@RequestBody BorrowDto d){Integer active=jdbc.queryForObject("SELECT COUNT(*) FROM borrow_record WHERE reader_id=? AND status='BORROWED'",Integer.class,d.readerId);Integer max=jdbc.queryForObject("SELECT max_borrow_count FROM reader WHERE id=?",Integer.class,d.readerId);if(active>=max)throw new BusinessException("已达到最大借阅数量");Map<String,Object>copy=jdbc.queryForMap("SELECT id,book_id FROM book_copy WHERE barcode=? AND status='AVAILABLE' FOR UPDATE",d.barcode);Long copyId=((Number)copy.get("id")).longValue(),bookId=((Number)copy.get("book_id")).longValue();BorrowRecord r=new BorrowRecord();r.setReaderId(d.readerId);r.setBookId(bookId);r.setCopyId(copyId);r.setBorrowTime(LocalDateTime.now());r.setDueTime(LocalDateTime.now().plusDays(30));r.setRenewCount(0);r.setStatus("BORROWED");r.setOperatorId(d.operatorId);borrows.insert(r);jdbc.update("UPDATE book_copy SET status='BORROWED' WHERE id=?",copyId);jdbc.update("UPDATE book SET available_copies=available_copies-1,borrow_count=borrow_count+1 WHERE id=?",bookId);return Result.ok();}
@PutMapping("/api/borrows/{id}/return")@Transactional public Result<Void>returnBook(@PathVariable Long id){BorrowRecord r=borrows.selectById(id);if(r==null||!"BORROWED".equals(r.getStatus()))throw new BusinessException("当前记录不能归还");r.setReturnTime(LocalDateTime.now());r.setStatus(r.getDueTime().isBefore(LocalDateTime.now())?"OVERDUE_RETURNED":"RETURNED");borrows.updateById(r);jdbc.update("UPDATE book_copy SET status='AVAILABLE' WHERE id=?",r.getCopyId());jdbc.update("UPDATE book SET available_copies=available_copies+1 WHERE id=?",r.getBookId());if("OVERDUE_RETURNED".equals(r.getStatus())){long days=Math.max(1,java.time.Duration.between(r.getDueTime(),r.getReturnTime()).toDays());jdbc.update("INSERT INTO fine_record(borrow_id,reader_id,amount,status) VALUES(?,?,?,'UNPAID')",r.getId(),r.getReaderId(),days*0.5);}return Result.ok();}
@PutMapping("/api/borrows/{id}/renew")public Result<Void>renew(@PathVariable Long id){BorrowRecord r=borrows.selectById(id);if(r==null||!"BORROWED".equals(r.getStatus()))throw new BusinessException("当前记录不能续借");if(r.getRenewCount()>=2)throw new BusinessException("已达到最大续借次数");if(r.getDueTime().isBefore(LocalDateTime.now()))throw new BusinessException("逾期图书不能续借");r.setRenewCount(r.getRenewCount()+1);r.setDueTime(r.getDueTime().plusDays(15));borrows.updateById(r);return Result.ok();}
@GetMapping("/api/reservations")public Result<List<Map<String,Object>>>reservations(){return Result.ok(reservations.searchAll());}
@PostMapping("/api/reservations")public Result<Void>reserve(@RequestBody Reservation r){if(reservations.exists(new LambdaQueryWrapper<Reservation>().eq(Reservation::getReaderId,r.getReaderId()).eq(Reservation::getBookId,r.getBookId()).in(Reservation::getStatus,"WAITING","AVAILABLE")))throw new BusinessException("请勿重复预约");Long count=reservations.selectCount(new LambdaQueryWrapper<Reservation>().eq(Reservation::getBookId,r.getBookId()).eq(Reservation::getStatus,"WAITING"));r.setQueueNo(count.intValue()+1);r.setReserveTime(LocalDateTime.now());r.setStatus("WAITING");r.setNotified(0);reservations.insert(r);return Result.ok();}
@DeleteMapping("/api/reservations/{id}")public Result<Void>cancel(@PathVariable Long id){Reservation r=reservations.selectById(id);r.setStatus("CANCELLED");reservations.updateById(r);return Result.ok();}
@Data public static class BorrowDto{private Long readerId;private String barcode;private Long operatorId;}}
